INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind Zugriffskontrollen eine technische Maßnahme zur IT-Sicherheit?', 2, '[{"text": "Ja", "correct": true, "because": "Schützen vor unbefugtem Zugriff"}, {"text": "Nein", "correct": false, "because": "Sie sind essenziell"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Hauptziel verfolgen Zugriffskontrollen?', 3, '[{"text": "Zugriff nur für Berechtigte ermöglichen", "correct": true, "because": "Sichert Daten"}, {"text": "Daten verschlüsseln", "correct": false, "because": "Andere Maßnahme"}, {"text": "Netzwerk trennen", "correct": false, "because": "Andere Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Zugriffskontrollen schützen sensible Daten. b) Sie sind nur für Netzwerke relevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, auch lokal"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methoden gehören zu Zugriffskontrollen?', 4, '[{"text": "Passwörter", "correct": true, "because": "Authentifizierung"}, {"text": "Unklare Prozesse", "correct": false, "because": "Widerspricht Klarheit"}, {"text": "Berechtigungsstufen", "correct": true, "because": "Definiert Zugriff"}, {"text": "Biometrie", "correct": true, "because": "Erhöhte Sicherheit"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein System ohne Zugriffskontrollen sicher sein?', 2, '[{"text": "Nein", "correct": true, "because": "Zugriff unsicher"}, {"text": "Ja", "correct": false, "because": "Risiko erhöht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielen Zugriffskontrollen im Datenschutz?', 3, '[{"text": "Schutz vor unbefugtem Datenzugriff", "correct": true, "because": "Sichert Vertraulichkeit"}, {"text": "Datenverfügbarkeit", "correct": false, "because": "Anderes Schutzziel"}, {"text": "Datenmanipulation", "correct": false, "because": "Integrität"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind Zugriffskontrollen nur für große Unternehmen relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Systeme"}, {"text": "Ja", "correct": false, "because": "Breite Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgabe hat eine Berechtigungsstufe?', 3, '[{"text": "Definiert Zugriffsrechte", "correct": true, "because": "Regelt Berechtigungen"}, {"text": "Daten verschlüsseln", "correct": false, "because": "Andere Maßnahme"}, {"text": "Netzwerk trennen", "correct": false, "because": "Andere Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Zugriffskontrollen nutzen Passwörter. b) Sie schützen nur vor externen Bedrohungen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, auch intern"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert ohne Zugriffskontrollen?', 3, '[{"text": "Unbefugte können Daten einsehen", "correct": true, "because": "Kein Schutz"}, {"text": "Daten schneller übertragen", "correct": false, "because": "Unsinn"}, {"text": "Systeme sicherer", "correct": false, "because": "Gegenteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann Zugriffskontrolle ohne Authentifizierung funktionieren?', 2, '[{"text": "Nein", "correct": true, "because": "Identität nötig"}, {"text": "Ja", "correct": false, "because": "Unrealistisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Beispiel zeigt eine Zugriffskontrolle?', 3, '[{"text": "Login mit Benutzername und Passwort", "correct": true, "because": "Konkret und real"}, {"text": "Daten löschen", "correct": false, "because": "Keine Maßnahme"}, {"text": "Netzwerk trennen", "correct": false, "because": "Andere Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist Zugriffskontrolle nur für sensible Daten relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Alle Daten schützbar"}, {"text": "Ja", "correct": false, "because": "Breite Nutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale hat eine Zugriffskontrolle?', 4, '[{"text": "Authentifizierung", "correct": true, "because": "Prüft Identität"}, {"text": "Unklare Rechte", "correct": false, "because": "Widerspricht Klarheit"}, {"text": "Berechtigungsverwaltung", "correct": true, "because": "Definiert Zugriff"}, {"text": "Protokollierung", "correct": true, "because": "Nachverfolgbarkeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen Zugriffskontrollen dokumentiert werden?', 2, '[{"text": "Ja", "correct": true, "because": "Nachweis wichtig"}, {"text": "Nein", "correct": false, "because": "Dokumentation hilft"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode unterstützt Zugriffskontrollen?', 3, '[{"text": "Rollenbasierte Zugriffskontrolle (RBAC)", "correct": true, "because": "Regelt Rechte"}, {"text": "Daten verschlüsseln", "correct": false, "because": "Andere Maßnahme"}, {"text": "Netzwerk trennen", "correct": false, "because": "Andere Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann Zugriffskontrolle ohne Passwörter funktionieren?', 2, '[{"text": "Ja", "correct": true, "because": "Biometrie möglich"}, {"text": "Nein", "correct": false, "because": "Alternativen vorhanden"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor gefährdet Zugriffskontrollen?', 3, '[{"text": "Schwache Authentifizierung", "correct": true, "because": "Leicht zu umgehen"}, {"text": "Hohe Geschwindigkeit", "correct": false, "because": "Irrelevant"}, {"text": "Gute Dokumentation", "correct": false, "because": "Unterstützt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Zugriffskontrollen schützen vor Datenlecks. b) Sie sind nur für Software relevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, auch Hardware"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Nutzen von Zugriffskontrollen?', 3, '[{"text": "Datensicherheit durch Zugriffsbeschränkung", "correct": true, "because": "Schützt Vertraulichkeit"}, {"text": "Maximale Offenheit", "correct": false, "because": "Widerspricht Zweck"}, {"text": "Keine Kontrolle", "correct": false, "because": "Fördert Sicherheit"}]');
